1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { SftpServer } from "../lib/sftp";
4	import { withServerSsh, exec, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
5	import {
6	  controlSpec,
7	  isGameFamily,
8	  isPowerAction,
9	  remoteLocateDir,
10	  runRcon,
11	  parsePlayers,
12	  computeNextRun,
13	  computeNextIntervalRun,
14	  shq,
15	  isSafeRemotePath,
16	  GAME_BACKUP_DIR,
17	  readGameLogs,
18	  logTrackingSpec,
19	  type GameControlSpec,
20	} from "../lib/game-control";
21	import { checkGamePortOpen, gamePortForServer, gamePortBoundInGuest } from "./provision-health";
22	import type { Job } from "@prisma/client";
23	
24	/**
25	 * How long GAME_POWER's post-action port check waits for the game process to
26	 * bind its port before giving up. Deliberately much shorter than provisioning's
27	 * GAME_PORT_CHECK_TIMEOUT_MS (300s) — this runs synchronously from a customer
28	 * pressing Start/Restart in the dashboard, not an unattended provision, and
29	 * most families that are going to come up at all do so in a few seconds once
30	 * systemd reports the unit active. A slow-installing family blocking on this
31	 * only delays the SUCCESS notification, never falsely reports failure early —
32	 * see the retry loop in checkGamePortOpen, which keeps trying for the whole window.
33	 */
34	const GAME_POWER_PORT_CHECK_TIMEOUT_MS = 30_000;
35	const GAME_POWER_PORT_CHECK_INTERVAL_MS = 3_000;
36	
37	/**
38	 * Game server control-panel worker handlers.
39	 *
40	 * Registered in worker/index.ts:
41	 *   GAME_POWER:  gamePower,
42	 *   GAME_BACKUP: gameBackup,
43	 * and `gameScheduleSweep()`, `playerTrackingSweep()` (RCON families) and
44	 * `logPlayerTrackingSweep()` (log-only families, e.g. Valheim) called on ~60s
45	 * timers.
46	 *
47	 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
48	 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
49	 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
50	 * and the root password is never surfaced in an error (only a trimmed remote stderr
51	 * is, which never contains it).
52	 *
53	 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
54	 */
55	
56	const CONTROL_FIELDS = {
57	  id: true,
58	  userId: true,
59	  hostname: true,
60	  status: true,
61	  rootPassword: true,
62	  rootPasswordEnc: true,
63	  sshPort: true,
64	  dedicatedIp: { select: { address: true } },
65	  node: { select: { publicIp: true } },
66	  osTemplate: { select: { family: true } },
67	  gamePlan: { select: { gameFamily: true } },
68	} as const;
69	
70	type ControlServer = {
71	  id: string;
72	  userId: string;
73	  hostname: string;
74	  status: string;
75	  rootPassword: string | null;
76	  rootPasswordEnc: string | null;
77	  sshPort: number | null;
78	  dedicatedIp: { address: string } | null;
79	  node: { publicIp: string } | null;
80	  osTemplate: { family: string | null };
81	  gamePlan: { gameFamily: string | null } | null;
82	};
83	
84	async function notify(userId: string, title: string, body?: string, href?: string) {
85	  try {
86	    await db.notification.create({ data: { userId, title, body, href } });
87	  } catch (e) {
88	    console.error("[game-control] notify failed", e);
89	  }
90	}
91	
92	function resolveSpec(server: ControlServer): GameControlSpec {
93	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
94	  if (!isGameFamily(fam)) throw new Error("not a game server");
95	  const spec = controlSpec(fam);
96	  if (!spec) throw new Error("no control spec for family");
97	  return spec;
98	}
99	
100	/**
101	 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
102	 * the family's control spec (compile-time constants); `action` is one of the three
103	 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
104	 * a successful action (the same discipline as worker/game-update.ts).
105	 */
106	function powerScript(spec: GameControlSpec, action: string): string {
107	  const hints = spec.serviceHints.map(shq).join(" ");
108	  return [
109	    `unit=""`,
110	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
111	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
112	    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
113	    `echo "NXGP:UNIT:$unit"`,
114	    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
115	    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
116	    `echo "NXGP:END"`,
117	  ].join("\n");
118	}
119	
120	/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
121	export async function gamePower(job: Job): Promise<void> {
122	  if (!job.serverId) throw new Error("game power: missing serverId");
123	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
124	  if (!server) throw new Error(`Server ${job.serverId} not found`);
125	  const spec = resolveSpec(server);
126	
127	  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
128	  const action = String(p.action ?? "");
129	  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
130	  const href = `/dashboard/servers/${server.id}?tab=manage`;
131	
132	  if (SANDBOX) {
133	    await notify(
134	      server.userId,
135	      `Game service ${action} (sandbox) on ${server.hostname}`,
136	      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
137	      href
138	    );
139	    return;
140	  }
141	  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");
142	
143	  // Optional pre-restart announce over RCON (best-effort; never fails the action).
144	  if (action === "restart" && p.announce && spec.rcon === "source") {
145	    try {
146	      await withServerSsh(server as SftpServer, (conn) =>
147	        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
148	      );
149	    } catch (e) {
150	      console.error("[game-control] restart announce failed (continuing)", e);
151	    }
152	  }
153	
154	  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
155	  const text = out.stdout;
156	  if (/NXGP:UNIT:NONE/.test(text)) {
157	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
158	    throw new Error("game power: no service unit found");
159	  }
160	  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
161	  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
162	  if (!/NXGP:END/.test(text) || rc !== 0) {
163	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
164	    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
165	  }
166	
167	  // FOUND LIVE 2026-09-20: this used to notify success on rc===0 + an END
168	  // marker alone, without ever checking `state` — so a unit that restarted
169	  // straight into "failed" (or stayed "activating"/crash-looping) was still
170	  // reported to the customer as "restarted (now failed)", i.e. success. A
171	  // `Restart=always` unit around a crash-looping container (exactly what a
172	  // wrong-Java-version Minecraft image produces — see
173	  // lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS) reports "active" between
174	  // crashes just as readily as a genuinely healthy server, so `systemctl`
175	  // alone was never going to be enough either way.
176	  if (action !== "stop" && state !== "active") {
177	    await notify(
178	      server.userId,
179	      `Could not ${action} the ${spec.label} service`,
180	      `${spec.label} on ${server.hostname} is "${state}" after the ${action}, not active. ` +
181	        `Diagnose with: systemctl status <unit> ; journalctl -u <unit> -n 50`,
182	      href
183	    );
184	    throw new Error(`game power: ${action} left service in state=${state}`);
185	  }
186	
187	  // Real port-bound check — the same in-guest positive-confirmation path
188	  // PROVISION uses (worker/provision-health.ts's checkGamePortOpen +
189	  // gamePortBoundInGuest), reused here for the other place this class of bug
190	  // hid: a systemd unit reporting "active" proves the OBJECT exists, never
191	  // that the game process inside actually bound its port. Best-effort and
192	  // deliberately short (GAME_POWER_PORT_CHECK_TIMEOUT_MS) — families with no
193	  // GAME_PORT entry, or a NAT server whose game port isn't forwarded, skip
194	  // this silently rather than block or falsely fail on a check that can't
195	  // mean anything for them.
196	  if (action !== "stop" && state === "active") {
197	    const game = gamePortForServer(server);
198	    const checkHost = server.dedicatedIp?.address ?? server.node?.publicIp ?? null;
199	    if (game && checkHost) {
200	      const portCheck = await checkGamePortOpen(checkHost, game.port, game.protocol, {
201	        timeoutMs: GAME_POWER_PORT_CHECK_TIMEOUT_MS,
202	        intervalMs: GAME_POWER_PORT_CHECK_INTERVAL_MS,
203	        verifyBound: () => gamePortBoundInGuest(server as SftpServer, game.port, game.protocol),
204	      });
205	      if (!portCheck.ok) {
206	        await notify(
207	          server.userId,
208	          `${spec.label} service ${action}ed, but the game never came online`,
209	          `systemd reports ${server.hostname} as active, but nothing is actually answering on ` +
210	            `${game.port}/${game.protocol}: ${portCheck.error ?? "no further detail"}. Check the game's own logs — ` +
211	            `this usually means the server process itself failed to start even though its service is "running".`,
212	          href
213	        );
214	        throw new Error(`game power: ${action} reported active but port ${game.port}/${game.protocol} never bound: ${portCheck.error ?? ""}`);
215	      }
216	    }
217	  }
218	
219	  await notify(
220	    server.userId,
221	    `${spec.label} service ${action}ed on ${server.hostname}`,
222	    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
223	    href
224	  );
225	
226	  // Persist the real systemd state so the dashboard's status dot can reflect
227	  // it. GAME_POWER only ever touches the game SERVICE inside the VM, never
228	  // `Server.status` (the VM's own power state) — those are genuinely
229	  // different things, but the panel's "Online/Offline" label was reading
230	  // `Server.status` alone, so a customer who stopped just their game service
231	  // (VM still up) kept seeing "Online" no matter what they did. Found live
232	  // 2026-09-09 via a real customer confused why "Status: Online" never
233	  // changed after repeated stop/start attempts. `_serviceState` follows the
234	  // same gameConfig-internal-marker convention as `_real`/`_realOk`/
235	  // `_appliedAt` elsewhere in this file's siblings — no schema migration
236	  // needed for what's fundamentally transient, best-effort runtime state.
237	  try {
238	    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
239	    const gameConfig = { ...(fresh?.gameConfig as Record<string, unknown> | null ?? {}), _serviceState: state };
240	    await db.server.update({ where: { id: server.id }, data: { gameConfig } });
241	  } catch (e) {
242	    console.error(`[game-control] could not persist _serviceState for ${server.hostname}`, e);
243	  }
244	}
245	
246	/** GAME_BACKUP — archive the world/save dir into a downloadable .tar.gz. */
247	export async function gameBackup(job: Job): Promise<void> {
248	  if (!job.serverId) throw new Error("game backup: missing serverId");
249	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
250	  if (!server) throw new Error(`Server ${job.serverId} not found`);
251	  const spec = resolveSpec(server);
252	  const href = `/dashboard/servers/${server.id}?tab=manage`;
253	
254	  if (SANDBOX) {
255	    await notify(server.userId, `World backup created (sandbox) on ${server.hostname}`, `Sandbox only — no VM was contacted for the ${spec.label} world backup.`, href);
256	    return;
257	  }
258	  if (server.status !== "RUNNING") throw new Error("game backup: VM is not running");
259	
260	  const outcome = await withServerSsh(server as SftpServer, async (conn) => {
261	    const dir = await remoteLocateDir(conn, spec.dataRoots);
262	    if (!dir || !isSafeRemotePath(dir)) return { ok: false, msg: "Could not locate the world/save directory." };
263	    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
264	    // from the located (allowlisted) dir; every value interpolated is single-quoted.
265	    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
266	    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}.tar.gz`;
267	    const parent = dir.replace(/\/[^/]+$/, "") || "/";
268	    const base = dir.replace(/^.*\//, "");
269	    const script =
270	      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
271	      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
272	      `stat -c '%s' ${shq(archive)}`;
273	    const r = await exec(conn, script, SETUP_TIMEOUT_MS);
274	    if (r.code !== 0) return { ok: false, msg: (r.stderr || r.stdout).trim().slice(0, 200) || "tar failed" };
275	    const size = Number(r.stdout.trim().split(/\r?\n/).pop());
276	    return { ok: true, archive, size: Number.isFinite(size) ? size : 0 };
277	  });
278	
279	  if (!outcome.ok) {
280	    await notify(server.userId, `World backup failed on ${server.hostname}`, outcome.msg, href);
281	    throw new Error(`game backup failed: ${outcome.msg}`);
282	  }
283	  const mb = ((outcome.size ?? 0) / (1024 * 1024)).toFixed(1);
284	  await notify(
285	    server.userId,
286	    `${spec.label} world backup ready on ${server.hostname}`,
287	    `Backed up your world (${mb} MB). Download it from the Manage → Worlds tab.`,
288	    href
289	  );
290	}
291	
292	/**
293	 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
294	 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
295	 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
296	 * interval-based). Idempotent / safe on a timer.
297	 */
298	export async function gameScheduleSweep(): Promise<void> {
299	  const now = new Date();
300	  const due = await db.gameSchedule.findMany({
301	    where: { enabled: true, nextRunAt: { lte: now } },
302	    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
303	    take: 100,
304	  });
305	  if (due.length === 0) return;
306	
307	  for (const s of due) {
308	    // Always advance the clock first so a server that is down / mid-operation does
309	    // not cause the same row to be reselected every tick.
310	    const nextRunAt = s.intervalMinutes
311	      ? computeNextIntervalRun(s.intervalMinutes, now)
312	      : computeNextRun(s.hour, s.minute, now);
313	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
314	
315	    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
316	    if (!isGameFamily(fam)) continue;
317	    if (s.server.status !== "RUNNING") continue;
318	
319	    if (s.kind === "command" && s.command) {
320	      // Send RCON command directly (e.g. save-all, weather clear).
321	      const spec = controlSpec(fam);
322	      if (!spec || spec.rcon === "none") continue;
323	      // Load full server for SSH access.
324	      const server = await db.server.findUnique({ where: { id: s.server.id }, select: CONTROL_FIELDS });
325	      if (!server) continue;
326	      try {
327	        await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
328	      } catch {
329	        // Best-effort: command schedules silently skip on failure.
330	      }
331	    } else {
332	      // Restart schedule: check for busy jobs first.
333	      const busy = await db.job.count({
334	        where: {
335	          serverId: s.server.id,
336	          status: { in: ["QUEUED", "RUNNING"] },
337	          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
338	        },
339	      });
340	      if (busy > 0) continue;
341	
342	      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
343	    }
344	  }
345	}
