347	/**
348	 * Track player join/leave events by comparing the live RCON player list against
349	 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
350	 *
351	 * For each RUNNING game server with a gamePlan:
352	 *   - NEW players (in RCON but no open session) → create a PlayerSession
353	 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
354	 *   - STILL ONLINE → no-op
355	 *
356	 * Per-server try/catch so one unreachable VM never blocks the sweep.
357	 */
358	export async function playerTrackingSweep(): Promise<void> {
359	  if (SANDBOX) return;
360	
361	  const servers = await db.server.findMany({
362	    where: { status: "RUNNING", gamePlanId: { not: null } },
363	    select: CONTROL_FIELDS,
364	  });
365	
366	  const now = new Date();
367	
368	  for (const server of servers) {
369	    try {
370	      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
371	      if (!isGameFamily(fam)) continue;
372	      const spec = controlSpec(fam);
373	      if (!spec || spec.rcon !== "source" || !spec.listCommand) continue;
374	
375	      // Get online players via RCON
376	      const res = await withServerSsh(server as SftpServer, (conn) =>
377	        runRcon(conn, spec, spec.listCommand!)
378	      );
379	      if (!res.ok) continue;
380	      const { players: onlinePlayers } = parsePlayers(spec.family, res.response);
381	      const onlineNames = new Set(onlinePlayers.map((p) => p.name.toLowerCase()));
382	
383	      // Get open sessions for this server
384	      const openSessions = await db.playerSession.findMany({
385	        where: { serverId: server.id, leftAt: null },
386	      });
387	      const sessionByName = new Map(
388	        openSessions.map((s) => [s.playerName.toLowerCase(), s])
389	      );
390	
391	      // NEW players: in RCON but no open session
392	      for (const p of onlinePlayers) {
393	        if (!sessionByName.has(p.name.toLowerCase())) {
394	          await db.playerSession.create({
395	            data: { serverId: server.id, playerName: p.name },
396	          });
397	        }
398	      }
399	
400	      // DEPARTED players: open session but not in RCON
401	      for (const session of openSessions) {
402	        if (!onlineNames.has(session.playerName.toLowerCase())) {
403	          await db.playerSession.update({
404	            where: { id: session.id },
405	            data: { leftAt: now },
406	          });
407	        }
408	      }
409	    } catch (e) {
410	      // Per-server: one failure must not break the sweep
411	      console.error(`[player-tracking] sweep failed for server ${server.id}`, e);
412	    }
413	  }
414	}
415	
416	/** Close the oldest still-open PlayerSession for `playerName` on `serverId`. */
417	async function closeOpenLogSession(serverId: string, playerName: string, inferred: boolean): Promise<void> {
418	  const open = await db.playerSession.findFirst({
419	    where: { serverId, playerName: { equals: playerName, mode: "insensitive" }, leftAt: null },
420	    orderBy: { joinedAt: "asc" },
421	  });
422	  if (open) {
423	    await db.playerSession.update({ where: { id: open.id }, data: { leftAt: new Date(), leftAtInferred: inferred } });
424	  }
425	}
426	
427	/**
428	 * Track player join/leave for game families with NO remote console (Valheim
429	 * today, via GAME_LOG_TRACKING in lib/game-control.ts) by tailing their own log
430	 * instead of RCON — `readGameLogs`, the exact same read-only path the Console
431	 * tab already uses. Runs every ~60s from the main loop, ALONGSIDE (not instead
432	 * of) `playerTrackingSweep` above — a server only ever matches one of the two,
433	 * since `logTrackingSpec` is only registered for families with `rcon: "none"`.
434	 *
435	 * THE REAL LIMITATION — read this before changing the inference below. Valheim's
436	 * dedicated-server log names a player on JOIN
437	 * (`Got character ZDOID from <name> : <id>`) but NOT on disconnect — a
438	 * disconnect only ever updates a running headcount (`... now N player(s)`). So
439	 * when the count drops we know FOR CERTAIN that one fewer player is connected,
440	 * but NOT which one. This sweep's handling of that gap:
441	 *
442	 *   - `onlineCount` always tracks the log's own headcount line exactly —
443	 *     ground truth, never guessed.
444	 *   - `onlineNames` (persisted on GameLogCursor) is a FIFO of names in join
445	 *     order. On a headcount decrement, the OLDEST believed-online name is
446	 *     popped and ITS PlayerSession is closed with `leftAtInferred: true` — a
447	 *     guess, not an observation, and wrong whenever the player who actually
448	 *     left isn't the longest-connected one of the group. `leftAtInferred` is
449	 *     surfaced in the UI (GamePlayerHistory) so this is never presented as
450	 *     fact.
451	 *   - If the count hits exactly 0, every remaining open session for the
452	 *     server is closed — that IS certain (nobody is connected), so those are
453	 *     NOT marked inferred.
454	 *   - If a JOIN names someone the FIFO still believes is online (drift from an
455	 *     earlier wrong guess), that stale session is closed first (inferred)
456	 *     before the fresh one opens, so drift self-corrects instead of piling up.
457	 *   - A count INCREASE with no matching join line parsed in this batch is left
458	 *     alone rather than inventing a name — `onlineCount` still updates.
459	 *
460	 * Incremental tailing: `GameLogCursor.lastLine` is the last raw line this sweep
461	 * already processed; each run only walks lines after that mark in the new tail.
462	 * `readGameLogs` is capped at the last 500 lines (lib/game-control.ts), so a
463	 * server producing >500 log lines between two ~60s sweeps could skip events —
464	 * acceptable for Valheim's actual join/leave volume, but worth knowing if this
465	 * pattern is reused for a chattier log. If the previous marker line has rolled
466	 * completely out of the new tail, this run processes nothing (rather than risk
467	 * double-counting) and just re-marks the newest line. On a server's very first
468	 * sweep (no GameLogCursor row yet) nothing is back-filled as a join — there is
469	 * no way to know when an already-connected player actually joined — so the
470	 * cursor is seeded silently and tracking starts clean from the next line on.
471	 */
472	export async function logPlayerTrackingSweep(): Promise<void> {
473	  if (SANDBOX) return;
474	
475	  const servers = await db.server.findMany({
476	    where: { status: "RUNNING", gamePlanId: { not: null } },
477	    select: CONTROL_FIELDS,
478	  });
479	
480	  for (const server of servers) {
481	    try {
482	      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
483	      if (!isGameFamily(fam)) continue;
484	      const spec = controlSpec(fam);
485	      const tracking = logTrackingSpec(fam);
486	      if (!spec || !tracking) continue; // only families with a registered log-tracking spec
487	
488	      const logRes = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec, 500));
489	      if (!logRes.ok) continue;
490	      const lines = logRes.lines;
491	      if (lines.length === 0) continue;
492	
493	      const cursor = await db.gameLogCursor.findUnique({ where: { serverId: server.id } });
494	      const isFirstSweep = !cursor;
495	
496	      let startIdx = lines.length; // default: process nothing (marker missing/rolled out)
497	      if (isFirstSweep) {
498	        startIdx = lines.length; // seed only — no back-fill, see doc comment
499	      } else if (cursor!.lastLine == null) {
500	        startIdx = 0; // a cursor existed but had no marker yet (shouldn't normally happen)
501	      } else {
502	        const idx = lines.lastIndexOf(cursor!.lastLine);
503	        startIdx = idx >= 0 ? idx + 1 : lines.length;
504	      }
505	
506	      let onlineNames: string[] = Array.isArray(cursor?.onlineNames) ? [...(cursor!.onlineNames as unknown as string[])] : [];
507	      let onlineCount = cursor?.onlineCount ?? 0;
508	
509	      for (let i = startIdx; i < lines.length; i++) {
510	        const line = lines[i];
511	
512	        const joinM = tracking.joinRe.exec(line);
513	        if (joinM) {
514	          const name = joinM[1].trim();
515	          if (name) {
516	            const dupIdx = onlineNames.findIndex((n) => n.toLowerCase() === name.toLowerCase());
517	            if (dupIdx >= 0) {
518	              // FIFO drift: we thought they were already online. Close the
519	              // stale (inferred) session before opening the real new one.
520	              onlineNames.splice(dupIdx, 1);
521	              await closeOpenLogSession(server.id, name, true);
522	            }
523	            onlineNames.push(name);
524	            await db.playerSession.create({ data: { serverId: server.id, playerName: name } });
525	          }
526	          continue;
527	        }
528	
529	        const countM = tracking.countRe.exec(line);
530	        if (countM) {
531	          const newCount = Number(countM[1]);
532	          if (Number.isFinite(newCount) && newCount !== onlineCount) {
533	            if (newCount === 0) {
534	              await db.playerSession.updateMany({
535	                where: { serverId: server.id, leftAt: null },
536	                data: { leftAt: new Date(), leftAtInferred: false },
537	              });
538	              onlineNames = [];
539	            } else if (newCount < onlineCount) {
540	              const drop = onlineCount - newCount;
541	              for (let d = 0; d < drop && onlineNames.length > 0; d++) {
542	                const leaver = onlineNames.shift()!;
543	                await closeOpenLogSession(server.id, leaver, true);
544	              }
545	            }
546	            onlineCount = newCount;
547	          }
548	        }
549	      }
550	
551	      const lastLine = lines[lines.length - 1];
552	      await db.gameLogCursor.upsert({
553	        where: { serverId: server.id },
554	        create: { serverId: server.id, lastLine, onlineNames, onlineCount },
555	        update: { lastLine, onlineNames, onlineCount },
556	      });
557	    } catch (e) {
558	      console.error(`[log-player-tracking] sweep failed for server ${server.id}`, e);
559	    }
560	  }
561	}
