268	/**
269	 * Connect to the game-server VM (host/port derived exactly like the file manager,
270	 * user "root", password `rootPassword`), run `fn`, and always close the session.
271	 */
272	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
273	  return new Promise((resolve, reject) => {
274	    const target = connectionTarget(server as any);
275	    if (!target) {
276	      reject(new Error("server is not reachable yet — connection details are pending"));
277	      return;
278	    }
279	    const password = serverRootPassword(server);
280	    if (!password) {
281	      reject(new Error("server has no root password set"));
282	      return;
283	    }
284	
285	    const conn = new Client();
286	    let settled = false;
287	    const finish = (err: Error | null, val?: T) => {
288	      if (settled) return;
289	      settled = true;
290	      try {
291	        conn.end();
292	      } catch {
293	        /* best-effort */
294	      }
295	      if (err) reject(err);
296	      else resolve(val as T);
297	    };
298	
299	    conn.on("ready", () => {
300	      conn.sftp((err, sftp) => {
301	        if (err) return finish(err);
302	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
303	      });
304	    });
305	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
306	    conn.connect({
307	      host: target.host,
308	      port: target.port,
309	      username: "root",
310	      password,
311	      readyTimeout: CONNECT_TIMEOUT_MS,
312	    });
313	  });
314	}
