316	/** Read a remote text file, or null if it does not exist. */
317	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
318	  return new Promise((resolve, reject) => {
319	    sftp.readFile(path, (err, data) => {
320	      if (err) {
321	        // ENOENT / no such file → null; anything else is a real error.
322	        const code = (err as NodeJS.ErrnoException).code;
323	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
324	          return resolve(null);
325	        }
326	        return reject(err);
327	      }
328	      resolve(data.toString("utf8"));
329	    });
330	  });
331	}
332	
333	/** Write a remote text file (overwrites). */
334	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
335	  return new Promise((resolve, reject) => {
336	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
337	  });
338	}
339	
340	/** Write a remote binary file (overwrites) — same as sftpWrite but skips utf8 re-encoding. */
341	function sftpWriteBinary(sftp: SFTPWrapper, path: string, content: Buffer): Promise<void> {
342	  return new Promise((resolve, reject) => {
343	    sftp.writeFile(path, content, (err) => (err ? reject(err) : resolve()));
344	  });
345	}
