347	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
348	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
349	  return new Promise((resolve, reject) => {
350	    conn.exec(cmd, (err, stream: ClientChannel) => {
351	      if (err) return reject(err);
352	      let stdout = "";
353	      let stderr = "";
354	      const timer = setTimeout(() => {
355	        try {
356	          stream.close();
357	        } catch {
358	          /* ignore */
359	        }
360	      }, EXEC_TIMEOUT_MS);
361	      stream
362	        .on("close", (code: number) => {
363	          clearTimeout(timer);
364	          resolve({ code: code ?? 0, stdout, stderr });
365	        })
366	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
367	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
368	    });
369	  });
370	}
