372	/**
373	 * Locate the first existing path: try explicit candidates via `test -f`, then a
374	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
375	 * Non-destructive — only reads.
376	 */
377	async function remoteLocate(
378	  conn: Client,
379	  candidates: string[],
380	  findRoots: string[],
381	  findName: string
382	): Promise<string | null> {
383	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
384	  const findExpr = findRoots.length
385	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
386	    : "true";
387	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
388	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
389	  return hit ?? null;
390	}
391	
392	/** Escape a value for single-quoted shell use. */
393	function shq(s: string): string {
394	  return s.replace(/'/g, "'\\''");
395	}
396	
397	/**
398	 * The systemd unit that supervises this family's game container, or null if the
399	 * guest has none.
400	 *
401	 * Every game family's setup script is rewritten at PROVISION time by
402	 * worker/index.ts's `wrapDockerGameService()` into `docker create` plus a
403	 * `<hint>.service` unit (`ExecStart=docker start -a <container>`,
404	 * `Restart=always`, `RestartSec=5`) — and that wrapper deliberately STRIPS
405	 * docker's own `--restart` policy, in its own words because "leaving both in
406	 * place makes the two supervisors fight over a crash-looping process". So on
407	 * every game server this platform provisions, systemd — not docker — owns the
408	 * container's lifecycle, and any apply path that stops or recreates a container
409	 * MUST go through it.
410	 *
411	 * Returns null when no unit resolves (a server provisioned before that wrapper
412	 * shipped, or a setup script that didn't match its `docker run -d --name X`
413	 * shape). There, docker's own restart policy is the only supervisor there is
414	 * and has to be preserved rather than replaced.
415	 *
416	 * The hints come from `lib/game-control.ts`'s per-family `controlSpec` — the
417	 * same list `worker/game-control.ts`'s power buttons resolve against, and the
418	 * same list `wrapDockerGameService` names the unit from ([0]) — so this can
419	 * never drift from the unit that actually got installed.
420	 */
421	async function resolveGameUnit(conn: Client, family: string): Promise<string | null> {
422	  const hints = controlSpec(family)?.serviceHints ?? [];
423	  if (!hints.length) return null;
424	  const probe = hints
425	    .map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`)
426	    .join(" ");
427	  const { stdout } = await execRemote(conn, probe);
428	  const hit = stdout
429	    .split(/\r?\n/)
430	    .map((s) => s.trim())
431	    .find((s) => s.endsWith(".service"));
432	  return hit ?? null;
433	}
