435	/** Dispatch to the correct family renderer. Exported for direct, real-server
436	 *  verification of a family's real-apply path (see REAL_APPLY_FAMILIES's own
437	 *  comment for what "confirmed" means) — not called externally otherwise. */
438	export async function applyRealConfig(server: SshServer, family: string, values: Values): Promise<ApplyOutcome> {
439	  return withSsh(server, async (conn, sftp) => {
440	    switch (family) {
441	      case "minecraft":
442	        return applyMinecraft(conn, sftp, values);
443	      case "rust":
444	        return applyRust(conn, sftp, values);
445	      case "valheim":
446	        return applyValheim(conn, sftp, values, server.gameVariant ?? "vanilla");
447	      case "cs2":
448	        return applyCs2(conn, sftp, values);
449	      case "palworld":
450	        return applyPalworld(conn, sftp, values);
451	      case "bedrock":
452	        return applyBedrock(conn, sftp, values);
453	      default:
454	        return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
455	    }
456	  });
457	}
