463	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
464	function updateKeyValue(content: string, updates: Record<string, string>): string {
465	  const lines = content.split(/\r?\n/);
466	  const seen = new Set<string>();
467	  for (let i = 0; i < lines.length; i++) {
468	    const trimmed = lines[i].trim();
469	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
470	    const eq = lines[i].indexOf("=");
471	    if (eq < 0) continue;
472	    const key = lines[i].slice(0, eq).trim();
473	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
474	      lines[i] = `${key}=${updates[key]}`;
475	      seen.add(key);
476	    }
477	  }
478	  for (const k of Object.keys(updates)) {
479	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
480	  }
481	  return lines.join("\n");
482	}
483	
484	/** Read a `key=value` file into a map (comments/blank lines ignored). */
485	function parseKeyValue(content: string): Record<string, string> {
486	  const out: Record<string, string> = {};
487	  for (const line of content.split(/\r?\n/)) {
488	    const t = line.trim();
489	    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
490	    const eq = line.indexOf("=");
491	    if (eq < 0) continue;
492	    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
493	  }
494	  return out;
495	}
