501	/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
502	function updateConvars(content: string, updates: Record<string, string>): string {
503	  const lines = content.split(/\r?\n/);
504	  const seen = new Set<string>();
505	  for (let i = 0; i < lines.length; i++) {
506	    const t = lines[i].trim();
507	    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
508	    const sp = t.search(/\s/);
509	    const key = sp < 0 ? t : t.slice(0, sp);
510	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
511	      lines[i] = `${key} ${updates[key]}`;
512	      seen.add(key);
513	    }
514	  }
515	  for (const k of Object.keys(updates)) {
516	    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
517	  }
518	  return lines.join("\n");
519	}
