528	/**
529	 * Read a container's current environment as a map.
530	 *
531	 * Recreating a container means re-supplying its WHOLE environment, not just the
532	 * keys being changed: the images this is used for get most of their defaults
533	 * from their own Dockerfile `ENV`s, and dropping those would silently reset
534	 * settings the customer never touched. `PATH` is excluded — the image always
535	 * injects a correct one, and carrying ours over would be wrong.
536	 */
537	async function readContainerEnv(conn: Client, container: string): Promise<Map<string, string> | null> {
538	  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
539	  if (inspect.code !== 0) return null;
540	  let envArr: string[];
541	  try {
542	    envArr = JSON.parse(inspect.stdout.trim());
543	  } catch {
544	    return null;
545	  }
546	  const envMap = new Map<string, string>();
547	  for (const entry of envArr) {
548	    const idx = entry.indexOf("=");
549	    if (idx < 0) continue;
550	    envMap.set(entry.slice(0, idx), entry.slice(idx + 1));
551	  }
552	  envMap.delete("PATH");
553	  return envMap;
554	}
