556	/** The exact image reference (repo:tag) a running container was created from. */
557	async function readContainerImage(conn: Client, container: string): Promise<string | null> {
558	  const res = await execRemote(conn, `docker inspect ${container} --format '{{.Config.Image}}'`);
559	  if (res.code !== 0) return null;
560	  const image = res.stdout.trim();
561	  return image || null;
562	}
