663	const MINECRAFT_CONTAINER = "mc";
664	/**
665	 * FOUND LIVE 2026-09-20: this used to be a single hardcoded
666	 * `itzg/minecraft-server:java21` applied to every Minecraft server
667	 * regardless of chosen VERSION — see lib/game-config.ts's
668	 * MINECRAFT_JAVA_CUTOVERS for the full incident and the real Mojang
669	 * Java-per-version cutovers. `minecraftImageForVersion` (imported above)
670	 * replaces it: the image tag is now derived from the VERSION being applied,
671	 * so a customer picking 26.1+ actually gets a Java-25 image instead of a
672	 * permanent crash loop. See the `imageInsufficient` check below for how this
673	 * is applied WITHOUT disrupting a server that's already running fine on a
674	 * Java version that already satisfies its own VERSION (never a forced
675	 * downgrade/lateral image swap — only a bump when what's running is
676	 * genuinely insufficient for the version it's being asked to run).
677	 */
678	/** Ports + volume exactly as prisma/catalog.ts's minecraft template provisions them. */
679	const MINECRAFT_RUN_FLAGS = "-p 25565:25565 -p 25575:25575 -v /opt/mc:/data --env-file /root/mc.env";
