681	async function applyMinecraft(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
682	  // TODO(paths): confirm the actual install dir/service name for the Minecraft
683	  // image. These candidates cover the common layouts; if none match we soft-fail
684	  // rather than create a stray server.properties in the wrong place.
685	  const path = await remoteLocate(
686	    conn,
687	    [
688	      "/opt/minecraft/server.properties",
689	      "/srv/minecraft/server.properties",
690	      "/home/minecraft/server.properties",
691	      "/minecraft/server.properties",
692	      "/root/minecraft/server.properties",
693	    ],
694	    ["/opt", "/srv", "/home"],
695	    "server.properties"
696	  );
697	  if (!path) {
698	    return { ok: false, applied: [], notes: ["Could not locate server.properties — nothing was changed (restart/redeploy needed once the config path is known)."] };
699	  }
700	
701	  const existing = await sftpRead(sftp, path);
702	  if (existing == null) {
703	    return { ok: false, applied: [], notes: [`server.properties disappeared at ${path} — nothing was changed.`] };
704	  }
705	
706	  // server.properties keys map 1:1 to the schema field keys. VERSION is a
707	  // docker env var, not a server.properties key — it's handled separately
708	  // below via container recreate, not written to this file.
709	  const updates: Record<string, string> = {};
710	  for (const [key, val] of Object.entries(v)) {
711	    if (key === "VERSION") continue;
712	    updates[key] = typeof val === "boolean" ? bool(val) : String(val);
713	  }
714	  const next = updateKeyValue(existing, updates);
715	  await sftpWrite(sftp, path, next);
716	
717	  const applied: string[] = [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`];
718	  const notes: string[] = [];
719	
720	  // VERSION: itzg's image defaults to tracking Mojang's newest release on every
721	  // container restart unless VERSION is pinned (see prisma/catalog.ts's own
722	  // comment on this field for the live incident that found it). Also checks
723	  // the running image against the Java version THIS version genuinely needs
724	  // (lib/game-config.ts's requiredJavaMajorForMinecraftVersion) — a server
725	  // provisioned (or last recreated) for an older version can be running an
726	  // image whose Java is too low for a newly-picked version even once VERSION
727	  // itself is correctly pinned. Found live 2026-09-06 on a Cobblemon server
728	  // this field was originally built for (VERSION pinned clean but the
729	  // container kept running a stale image's bundled JDK); found again live
730	  // 2026-09-20 on minecraft-qj4rxt, which picked 26.2 and got the platform's
731	  // then-single hardcoded :java21 image — Minecraft 26.1+ refuses to even
732	  // start under Java 21 ("requires running the server with Java 25 or
733	  // above"), a permanent crash loop.
734	  //
735	  // `imageInsufficient` only ever fires for a genuine shortfall (current Java
736	  // major < what the target version requires) — never for a server that's
737	  // already running on Java equal to or ABOVE what its version needs. That is
738	  // deliberate: bumping every server up to whatever image is "current" on
739	  // every settings save would be a disruptive, unnecessary recreate of
740	  // servers that are already working fine, which is exactly the failure mode
741	  // this fix must not introduce (existing java21 servers on old,
742	  // already-working versions must NOT be touched by this).
743	  const desiredVersion = v["VERSION"] != null ? String(v["VERSION"]) : null;
744	  if (desiredVersion) {
745	    const envMap = await readContainerEnv(conn, MINECRAFT_CONTAINER);
746	    const currentVersion = envMap?.get("VERSION") ?? null;
747	    const currentImage = await readContainerImage(conn, MINECRAFT_CONTAINER);
748	    const requiredJavaMajor = requiredJavaMajorForMinecraftVersion(desiredVersion);
749	    const currentJavaMajor = javaMajorOfMinecraftImage(currentImage);
750	    const imageInsufficient =
751	      currentImage !== null && (currentJavaMajor === null || currentJavaMajor < requiredJavaMajor);
752	    const desiredImage = minecraftImageForVersion(desiredVersion);
753	    if (envMap && (currentVersion !== desiredVersion || imageInsufficient)) {
754	      envMap.set("VERSION", desiredVersion);
755	      envMap.delete("JAVA_VERSION"); // stale, baked in by whatever image created this container — let the new image set its own
756	      await writeEnvFile(conn, sftp, "/root/mc.env", envMap);
757	      const res = await recreateGameContainer(conn, {
758	        family: "minecraft",
759	        container: MINECRAFT_CONTAINER,
760	        runFlags: MINECRAFT_RUN_FLAGS,
761	        image: desiredImage,
762	      });
763	      if (!res.ok) {
764	        notes.push(`Wrote settings, but pinning the Minecraft version failed: ${res.note}`);
765	      } else {
766	        const parts: string[] = [];
767	        if (currentVersion !== desiredVersion) {
768	          parts.push(
769	            currentVersion
770	              ? `pinned Minecraft version to ${desiredVersion} (was ${currentVersion})`
771	              : `pinned Minecraft version to ${desiredVersion} (previously untracked — following Mojang's newest release on every restart)`
772	          );
773	        }
774	        if (imageInsufficient)
775	          parts.push(
776	            `updated the server image to run Java ${requiredJavaMajor} (${desiredImage}), which this version requires` +
777	              (currentImage ? ` (was ${currentImage})` : "")
778	          );
779	        const summary = parts.join(" and ");
780	        applied.push(`${summary.charAt(0).toUpperCase()}${summary.slice(1)}, and restarted the server.`);
781	      }
782	    }
783	  }
784	
785	  // Best-effort live push via RCON for the live-editable fields; otherwise note a
786	  // restart. Wrapped so RCON problems never fail the apply.
787	  try {
788	    await tryMinecraftRcon(conn, next, v, notes);
789	  } catch (e) {
790	    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
791	    console.error("[game-config] minecraft rcon error", e);
792	  }
793	
794	  return {
795	    ok: true,
796	    applied,
797	    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
798	  };
799	}
