856	/**
857	 * The RCON port to talk to, from an untrusted `rcon.port` value.
858	 *
859	 * Accepts only a bare 1–65535 decimal; anything else (empty, non-numeric, out of
860	 * range, or carrying a shell payload) falls back to Minecraft's default 25575.
861	 * Returns a string because it is interpolated into a command line, and returning
862	 * the parsed digits — never the caller's original text — is what makes the value
863	 * safe by construction rather than by escaping.
864	 */
865	function rconPort(raw: string | undefined): string {
866	  const n = Number(String(raw ?? "").trim());
867	  if (!Number.isInteger(n) || n < 1 || n > 65535) return "25575";
868	  return String(n);
869	}
