896	/** Replace `<flag> <value>` in an argument string, or append the pair if absent. */
897	function upsertArg(args: string, flag: string, value: string): string {
898	  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
899	  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
900	  return re.test(args) ? args.replace(re, `$1${flag} ${value}`) : `${args} ${flag} ${value}`.trim();
901	}
902	
903	/** Strip `<flag> <value>` from an argument string entirely, if present. */
904	function removeArg(args: string, flag: string): string {
905	  const esc = flag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
906	  const re = new RegExp(`(^|\\s)${esc}\\s+\\S+`);
907	  return args.replace(re, "").trim();
908	}
