942	  const envMap = await readContainerEnv(conn, RUST_CONTAINER);
943	  if (!envMap) {
944	    return { ok: false, applied: [], notes: [`Could not find the "${RUST_CONTAINER}" container — nothing was changed.`] };
945	  }
946	
947	  const applied: string[] = [];
948	  const notes: string[] = [];
949	  for (const [key, val] of Object.entries(v)) {
950	    if (val == null) continue;
951	    const env = RUST_ENV_MAP[key];
952	    if (env) {
953	      envMap.set(env, String(val));
954	      applied.push(key);
955	    } else if (key === "pve") {
956	      // No RUST_SERVER_PVE exists. start.sh passes RUST_SERVER_STARTUP_ARGUMENTS
957	      // through verbatim ahead of the generated pairs, so it is the image's own
958	      // escape hatch for any convar it has no variable for.
959	      const args = envMap.get("RUST_SERVER_STARTUP_ARGUMENTS") ?? "-batchmode -load -nographics +server.secure 1";
