961	      applied.push(key);
962	    }
963	  }
964	  if (applied.length === 0) {
965	    return { ok: true, applied: [], notes: ["No changes to apply."] };
966	  }
967	
968	  await writeEnvFile(conn, sftp, "/root/rust.env", envMap);
969	
970	  const res = await recreateGameContainer(conn, {
971	    family: "rust",
972	    container: RUST_CONTAINER,
973	    runFlags: RUST_RUN_FLAGS,
974	    image: RUST_IMAGE,
975	  });
976	  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };
977	
978	  if (v["worldsize"] != null || v["seed"] != null) {
979	    notes.push("World size / seed only take effect on a fresh map — the existing save is kept until the next wipe.");
980	  }
981	  notes.push(
982	    "Rust reloads its whole map on restart, so your server will be offline for several minutes before players can rejoin."
983	  );
984	
985	  return { ok: true, applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`], notes };
986	}
