31	/**
32	 * How many attempts a retry window of `timeoutMs` at `intervalMs` cadence
33	 * allows, counting the first (immediate) attempt. Always at least 1, so a
34	 * misconfigured zero/negative timeout still tries once rather than looping
35	 * forever or never trying at all.
36	 */
37	export function attemptsFor(timeoutMs: number, intervalMs: number): number {
38	  if (!Number.isFinite(timeoutMs) || !Number.isFinite(intervalMs) || intervalMs <= 0) return 1;
39	  return Math.max(1, Math.floor(timeoutMs / intervalMs) + 1);
40	}
41	
42	export type CheckOnce = () => Promise<{ ok: true; detail?: string } | { ok: false; error: string }>;
43	
44	export type RetryResult =
45	  | { ok: true; detail?: string; attempts: number; elapsedMs: number }
46	  | { ok: false; error: string; attempts: number; elapsedMs: number };
47	
48	/**
49	 * Generic bounded retry: call `checkOnce` up to `attemptsFor(timeoutMs,
50	 * intervalMs)` times, sleeping `intervalMs` between attempts, stopping early
51	 * on the first success. `sleep` is injectable so tests can run this at real
52	 * speed with zero wall-clock delay instead of mocking timers.
53	 */
54	export async function retryCheck(
55	  checkOnce: CheckOnce,
56	  opts: { timeoutMs: number; intervalMs: number; sleep?: (ms: number) => Promise<void>; now?: () => number }
57	): Promise<RetryResult> {
58	  const sleep = opts.sleep ?? ((ms: number) => new Promise((resolve) => setTimeout(resolve, ms)));
59	  const now = opts.now ?? (() => Date.now());
60	  const attempts = attemptsFor(opts.timeoutMs, opts.intervalMs);
61	  const start = now();
62	  let lastError = "no attempt was made";
63	  for (let i = 0; i < attempts; i++) {
64	    const res = await checkOnce();
65	    if (res.ok) return { ok: true, detail: res.detail, attempts: i + 1, elapsedMs: now() - start };
66	    lastError = res.error;
67	    if (i < attempts - 1) await sleep(opts.intervalMs);
68	  }
69	  return { ok: false, error: lastError, attempts, elapsedMs: now() - start };
70	}
