96	/** The expected game port + transport for a server, or null (not a recognized game). */
97	export function gamePortForServer(server: ServerFamilyLike | null | undefined): { port: number; protocol: "tcp" | "udp" } | null {
98	  const fam = gameFamilyForServer(server);
99	  return fam ? GAME_PORT[fam] : null;
