102	// ---------------------------------------------------------------------------
103	// Real network I/O — single-attempt probes.
104	// ---------------------------------------------------------------------------
105	
106	/** Default per-attempt socket timeout — how long ONE connect (not the whole
107	 *  retry window) is allowed before giving up and trying again. */
108	export const TCP_ATTEMPT_TIMEOUT_MS = 5_000;
109	
110	/**
111	 * One TCP connect attempt, optionally requiring an SSH banner
112	 * ("SSH-2.0-...") rather than just a completed handshake — a closed port
113	 * that drops the connection can otherwise look indistinguishable from a real
114	 * refusal on some networks, so getting the actual banner is the proof.
115	 */
116	function tcpAttempt(
117	  host: string,
118	  port: number,
119	  opts: { timeoutMs: number; expectSshBanner: boolean }
120	): Promise<{ ok: true; detail?: string } | { ok: false; error: string }> {
121	  return new Promise((resolve) => {
122	    const socket = new net.Socket();
123	    let settled = false;
124	    let buf = "";
125	    const finish = (result: { ok: true; detail?: string } | { ok: false; error: string }) => {
126	      if (settled) return;
127	      settled = true;
128	      clearTimeout(timer);
129	      socket.removeAllListeners();
130	      socket.destroy();
131	      resolve(result);
132	    };
133	    const timer = setTimeout(() => finish({ ok: false, error: "timed out" }), opts.timeoutMs);
134	    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
135	    socket.once("connect", () => {
136	      if (!opts.expectSshBanner) finish({ ok: true });
137	      // else: wait for the banner line on "data" below.
138	    });
139	    if (opts.expectSshBanner) {
140	      socket.on("data", (chunk) => {
141	        buf += chunk.toString("utf8");
142	        if (buf.includes("\n") || buf.length >= 256) {
143	          const line = buf.trim();
144	          if (line.startsWith("SSH-")) finish({ ok: true, detail: line.slice(0, 120) });
145	          else finish({ ok: false, error: `connected but no SSH banner (got: ${line.slice(0, 80) || "<empty>"})` });
146	        }
147	      });
148	    }
149	    socket.connect(port, host);
150	  });
151	}
152	
153	/**
154	 * One UDP reachability probe. UDP has no handshake, so this cannot PROVE a
155	 * listener exists the way a TCP connect can — but on Linux, a datagram sent
156	 * to a UDP port nothing is bound to draws a prompt ICMP port-unreachable,
157	 * which node surfaces as an `ECONNREFUSED` error on a *connected* UDP socket.
158	 * No error within the window is treated as reachable. This is the same class
159	 * of "did the process actually bind the port" evidence the TCP check gives —
160	 * it would have caught the Terraria-style bug (container up, nothing bound)
161	 * on a UDP-only game exactly the same way.
162	 */
163	function udpAttempt(host: string, port: number, opts: { timeoutMs: number }): Promise<{ ok: true } | { ok: false; error: string }> {
164	  return new Promise((resolve) => {
165	    const socket = dgram.createSocket("udp4");
166	    let settled = false;
167	    const finish = (result: { ok: true } | { ok: false; error: string }) => {
168	      if (settled) return;
169	      settled = true;
170	      clearTimeout(timer);
171	      socket.removeAllListeners();
172	      socket.close();
173	      resolve(result);
174	    };
175	    const timer = setTimeout(() => finish({ ok: true }), opts.timeoutMs);
176	    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
177	    socket.connect(port, host, () => {
178	      socket.send(Buffer.from([0]), (err) => {
179	        if (err) finish({ ok: false, error: (err as NodeJS.ErrnoException).code ?? err.message });
180	      });
181	    });
182	  });
183	}
