189	/**
190	 * Retries every ~5s for up to 2 minutes. SSH normally comes up within
191	 * seconds of the guest booting — cloud-init's user/ssh-key modules run near
192	 * the START of boot, well before the game/app install `runcmd` — and by the
193	 * time provision() reaches this check it has usually already waited up to
194	 * 180s for the guest agent, so sshd has almost always had time. Two minutes
195	 * of its own headroom on top covers the case where the agent never answers
196	 * (not every image ships qemu-guest-agent) but sshd is merely slow.
197	 */
198	export const SSH_CHECK_TIMEOUT_MS = 120_000;
199	export const SSH_CHECK_INTERVAL_MS = 5_000;
200	
201	/**
202	 * Real TCP connect + SSH banner check against the server's actual reachable
203	 * address (caller passes the dedicated IP, or the NAT host + assigned SSH
204	 * port — see worker/index.ts's `dedicated`/`sshPort` computation, reused
205	 * here rather than recomputed).
206	 */
207	export async function checkSshReachable(
208	  host: string,
209	  port: number,
210	  opts?: { timeoutMs?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void> }
211	): Promise<RetryResult> {
212	  return retryCheck(() => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: true }), {
213	    timeoutMs: opts?.timeoutMs ?? SSH_CHECK_TIMEOUT_MS,
214	    intervalMs: opts?.intervalMs ?? SSH_CHECK_INTERVAL_MS,
215	    sleep: opts?.sleep,
216	  });
217	}
