314	/**
315	 * Real TCP-or-UDP connect check (per `GAME_PORT`'s `protocol`) against the
316	 * server's own address at the game's actual listen port — see
317	 * `gamePortForServer`. Reuses the caller's already-computed `ip` (the
318	 * dedicated public IP, or the NAT server's private address) rather than
319	 * recomputing it.
320	 *
321	 * NOTE on NAT servers: only SSH gets an automatic port-forward at provision
322	 * time (`syncPortForwardsBestEffort`); the game's own port is forwarded only
323	 * if the customer adds a `PortForward` for it (lib/actions-server.ts) — a
324	 * separate, pre-existing product gap this task does not touch. Checking
325	 * against the VM's own address (not the public NAT address) still verifies
326	 * the thing this check exists to catch — the game process itself bound the
327	 * port — independent of whether that port is yet forwarded to the internet.
328	 */
329	export async function checkGamePortOpen(
330	  host: string,
331	  port: number,
332	  protocol: "tcp" | "udp",
333	  opts?: {
334	    timeoutMs?: number;
335	    intervalMs?: number;
336	    sleep?: (ms: number) => Promise<void>;
337	    /**
338	     * Positive confirmation that the game really is bound to the port, read
339	     * from inside the guest — see `procNetHasPort` and the UDP note above.
340	     * `true` = bound, `false` = definitely not bound, `null` = could not tell
341	     * (never held against the server). Required to make the UDP path mean
342	     * anything; harmless and still useful as a second opinion for TCP.
343	     */
344	    verifyBound?: () => Promise<boolean | null>;
345	  }
346	): Promise<RetryResult> {
347	  const attempt: CheckOnce =
348	    protocol === "tcp"
349	      ? () => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: false })
350	      : () => udpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS });
351	  const verify = opts?.verifyBound;
352	  const checkOnce: CheckOnce = verify
353	    ? async () => {
354	        const r = await attempt();
355	        if (!r.ok) return r;
356	        const bound = await verify();
357	        if (boundVerdictPasses(protocol, bound)) return r;
358	        return {
359	          ok: false,
360	          error:
361	            bound === false
362	              ? `the ${port}/${protocol} probe drew no refusal, but nothing inside the guest is bound to ` +
363	                `${port}/${protocol} — silence is not the game listening`
364	              : `the ${port}/udp probe drew no refusal, but the guest could not confirm anything is bound ` +
365	                `to ${port}/udp — for UDP that is no evidence at all, not a pass`,
366	        };
367	      }
368	    : attempt;
369	  return retryCheck(checkOnce, {
370	    timeoutMs: opts?.timeoutMs ?? GAME_PORT_CHECK_TIMEOUT_MS,
371	    intervalMs: opts?.intervalMs ?? GAME_PORT_CHECK_INTERVAL_MS,
372	    sleep: opts?.sleep,
373	  });
374	}
