376	/**
377	 * Is a socket bound to `port` present in a `/proc/net/{udp,udp6,tcp,tcp6}`
378	 * table? Pure parser over the raw table text so it is unit-testable; the
379	 * caller concatenates the guest's own tables plus each running container's
380	 * (`/proc/<pid>/net/...`), because a containerised game binds the port in its
381	 * OWN network namespace, not the guest's.
382	 *
383	 * WHY THIS EXISTS: `udpAttempt` resolves SUCCESS on timeout — for a
384	 * connectionless protocol there is nothing else a generic prober can do, since
385	 * a healthy game server has no obligation to answer a byte of nonsense. So the
386	 * UDP game-port check passed on silence, and silence is exactly what a guest
387	 * emits while a crash-looping container is between restarts (the packet is
388	 * dropped rather than refused). Caught live 2026-09-07: a The Forest order was
389	 * marked DONE and handed over as ready while its container had restarted 118
390	 * times, had never started the game at all ("Missing SERVER_STEAM_ACCOUNT_TOKEN
391	 * … Aborting server start"), and had nothing bound to any port. That is the
392	 * same "the system asserting something untrue" failure this whole module was
393	 * written to end, just on the protocol half nobody had checked.
394	 *
395	 * `st` is only meaningful for TCP (0A = LISTEN); UDP sockets have no listen
396	 * state, so a bound socket is all there is to find.
397	 */
398	/**
399	 * Given the in-guest binding verdict (`true` bound / `false` not bound / `null`
400	 * could not be determined), may this attempt count as the game port being open?
401	 *
402	 * The asymmetry between the protocols is the whole point. A completed TCP
403	 * connect is real evidence by itself, so the in-guest read is only a second
404	 * opinion and "could not ask" costs nothing. A UDP probe that draws no refusal
405	 * is NOT evidence — `udpAttempt` reports success on silence — so without an
406	 * in-guest answer the attempt has established nothing, and letting "unknown"
407	 * pass would put the check straight back to being a no-op that any transient
408	 * SSH hiccup unlocks. Attempts repeat across the whole retry window, so a blip
409	 * costs one attempt; only a guest that stays unreachable for the entire window
410	 * fails here, and that guest has a real problem regardless.
411	 */
412	export function boundVerdictPasses(protocol: "tcp" | "udp", bound: boolean | null): boolean {
413	  if (bound === true) return true;
414	  if (bound === false) return false;
415	  return protocol === "tcp";
416	}
417	
418	export function procNetHasPort(table: string, port: number, opts?: { tcpListeningOnly?: boolean }): boolean {
419	  if (!Number.isInteger(port) || port <= 0 || port > 65535) return false;
420	  const want = port.toString(16).toUpperCase().padStart(4, "0");
421	  for (const line of table.split("\n")) {
422	    const f = line.trim().split(/\s+/);
423	    // sl local_address rem_address st ...
424	    if (f.length < 4 || !f[1]?.includes(":")) continue;
425	    const local = f[1];
426	    const cut = local.lastIndexOf(":");
427	    if (local.slice(cut + 1).toUpperCase() !== want) continue;
428	    if (opts?.tcpListeningOnly && f[3] !== "0A") continue;
429	    // A socket bound to loopback INSIDE the container is bound to a network
430	    // nobody else is on — not the docker bridge, not the guest, certainly not a
431	    // player. Found live on Soulmask, whose admin port sits on 127.0.0.1:18888
432	    // in its namespace while `-p 18888:18888/tcp` publishes it: docker-proxy
433	    // accepts and the backend dial is refused. Counting that as "bound" would
434	    // make this check agree with a port that is provably unreachable.
435	    if (isLoopbackAddrHex(local.slice(0, cut))) continue;
436	    return true;
437	  }
438	  return false;
439	}
440	
441	/** Is a `/proc/net` hex local address a loopback one (127.0.0.0/8, ::1, or
442	 *  an IPv4-mapped loopback)? Addresses are little-endian per 4-byte word, so
443	 *  127.0.0.1 appears as `0100007F`. */
444	function isLoopbackAddrHex(addr: string): boolean {
445	  const up = addr.toUpperCase();
446	  if (up.length === 8) return up.slice(6, 8) === "7F";
447	  if (up.length === 32) {
448	    if (up === "00000000000000000000000001000000") return true; // ::1
449	    if (up.startsWith("0000000000000000FFFF0000")) return isLoopbackAddrHex(up.slice(24)); // ::ffff:127.x.x.x
450	    return false;
451	  }
452	  return false;
453	}
