455	// ---------------------------------------------------------------------------
456	// In-guest positive confirmation — the only way to tell "the game process
457	// really bound its port" from "the container/service object exists".
458	// ---------------------------------------------------------------------------
459	
460	/**
461	 * Ask the guest whether anything is really bound to the game's port — the
462	 * positive evidence `checkGamePortOpen`'s UDP path cannot get from outside
463	 * (see `procNetHasPort` for why silence is not proof).
464	 *
465	 * Reads the network namespace of every RUNNING container, falling back to the
466	 * guest's own only when no container is running. The fallback order matters
467	 * and is not a detail: `docker-proxy` binds every published port in the
468	 * guest's ROOT namespace for as long as the container is up, whether or not
469	 * the game inside ever listens — verified live on The Forest, whose guest
470	 * showed `0.0.0.0:27015` bound while the game had never started. Counting the
471	 * root namespace whenever a container runs would reproduce the very false
472	 * positive this function exists to remove. A `--network host` container is
473	 * unaffected: its namespace IS the root one.
474	 *
475	 * Exported from this side-effect-free module (rather than kept private in
476	 * worker/index.ts, where it originally lived) so `worker/game-control.ts` can
477	 * reuse the exact same in-guest check for GAME_POWER's start/restart —
478	 * importing worker/index.ts itself is unsafe anywhere else, since it runs a
479	 * top-level job-polling `main()` loop on import.
480	 *
481	 * ADDED TO GAME_POWER 2026-09-20: every existing health signal for
482	 * GAME_UPDATE and GAME_POWER start/restart only ever checked that the
483	 * container/systemd-service OBJECT existed and `systemctl` reported it
484	 * active — never that the actual game process bound its port. That is
485	 * precisely how a Minecraft server hardcoded onto the wrong Java image
486	 * (crash-looping every ~15s, `docker logs` full of a clear Java-version
487	 * error) went undetected: the systemd unit around a `Restart=always`
488	 * container reports "active" between crashes just as readily as it would for
489	 * a genuinely healthy server. See lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS
490	 * for the incident this shares its root cause with.
491	 *
492	 * Opens its own SSH connection (does not reuse a caller's already-open one) —
493	 * pure reads, nothing on the guest is touched.
494	 *
495	 * Returns `null` — never `false` — for anything it could not determine (SSH
496	 * failed, no marker in the output), so an unreachable guest can never turn a
497	 * healthy server into a falsely-failed check.
498	 */
499	export async function gamePortBoundInGuest(
500	  probeServer: { id: string; rootPassword: string | null; rootPasswordEnc?: string | null; sshPort: number | null; dedicatedIp?: { address: string } | null; node?: { publicIp: string } | null },
501	  port: number,
502	  protocol: "tcp" | "udp"
503	): Promise<boolean | null> {
504	  const base = protocol === "tcp" ? "tcp" : "udp";
505	  try {
506	    return await withServerSsh(probeServer as any, async (conn) => {
507	      const r = await exec(
508	        conn,
509	        // `docker ps` failing and `docker ps` finding nothing look identical in
510	        // its output, so its exit status is captured explicitly: a daemon that
511	        // could not be asked must read as UNKNOWN, never as "no containers, so
512	        // look in the root namespace" — where docker-proxy would answer for a
513	        // dead game.
514	        `if ids=$(docker ps -q 2>/dev/null); then dok=1; else dok=0; fi; ` +
515	          `files=""; ` +
516	          `for pid in $(docker inspect -f '{{.State.Pid}}' ${"$"}ids 2>/dev/null); do ` +
517	          `case "${"$"}pid" in ''|0) continue;; esac; ` +
518	          `files="${"$"}files /proc/${"$"}pid/net/${base} /proc/${"$"}pid/net/${base}6"; done; ` +
519	          `if [ -z "${"$"}files" ]; then ` +
520	          `if [ "${"$"}dok" = 1 ] && [ -z "${"$"}ids" ]; then files="/proc/net/${base} /proc/net/${base}6"; ` +
521	          `else echo NXNET_UNKNOWN; exit 0; fi; fi; ` +
522	          `echo NXNET_BEGIN; cat ${"$"}files 2>/dev/null; echo NXNET_END`,
523	        QUICK_TIMEOUT_MS
524	      );
525	      const begin = r.stdout.indexOf("NXNET_BEGIN");
526	      const end = r.stdout.indexOf("NXNET_END");
527	      if (begin < 0 || end < begin) {
528	        console.warn(
529	          `[worker] ${probeServer.id}: could not read ${port}/${protocol} bindings from the guest ` +
530	            `(${r.stdout.includes("NXNET_UNKNOWN") ? "docker could not be queried" : "no marker in the reply"})`
531	        );
532	        return null;
533	      }
534	      const table = r.stdout.slice(begin + "NXNET_BEGIN".length, end);
535	      const bound = procNetHasPort(table, port, { tcpListeningOnly: protocol === "tcp" });
536	      if (!bound) {
537	        console.warn(`[worker] ${probeServer.id}: nothing in the guest is bound to ${port}/${protocol}`);
538	      }
539	      return bound;
540	    });
541	  } catch (e) {
542	    console.warn(
543	      `[worker] ${probeServer.id}: could not ask the guest about ${port}/${protocol} bindings: ${String((e as Error)?.message ?? e)}`
544	    );
545	    return null;
546	  }
547	}
