15	/**
16	 * Game-server auto-update handlers.
17	 *
18	 * `gameUpdate` runs the per-family update over SSH against the server's private
19	 * IP (the worker can reach vmbr1) and PROVES the outcome before saying anything
20	 * to the customer. `gameUpdateSweep` finds RUNNING game servers with
21	 * `autoUpdate=true` and enqueues GAME_UPDATE jobs for them — safe to call
22	 * periodically (it de-dupes on in-flight jobs).
23	 *
24	 * The remote command used to end `; true` with every step `|| true`, so it could
25	 * not exit non-zero and this handler always fired *"The latest server update was
26	 * applied and the service was restarted."* — unattended, every 6 hours, whether
27	 * or not steamcmd existed, a unit matched, or the service came back. The command
28	 * builder, the output parser and the verdict now live in lib/game-update-verify.ts
29	 * where they are tested; SSH failure is still a failure, but a clean SSH exit is
30	 * no longer evidence of anything.
31	 *
32	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
33	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
34	 */
35	
36	async function loadGameServer(serverId: string) {
37	  const server = await db.server.findUnique({
38	    where: { id: serverId },
39	    include: { osTemplate: true, dedicatedIp: true, node: true },
40	  });
41	  if (!server) throw new Error(`Server ${serverId} not found`);
42	  return server;
43	}
44	
45	async function notify(userId: string, title: string, body?: string, href?: string) {
46	  try {
47	    await db.notification.create({ data: { userId, title, body, href } });
48	  } catch (e) {
49	    console.error("[game-update] notify failed", e);
50	  }
51	}
52	
53	/**
54	 * Tell the customer once, not once per retry.
55	 *
56	 * The worker retries a failed job three times, and this one runs every six
57	 * hours; without this, a server whose steamcmd is missing would generate three
58	 * identical alarms per sweep, forever, and the customer would learn to ignore
59	 * them — which is the same outcome as not telling them.
60	 */
61	async function notifyFailureOnce(userId: string, serverId: string, title: string, body: string, href: string) {
62	  const since = new Date(Date.now() - 24 * 60 * 60_000);
63	  const dupe = await db.notification
64	    .findFirst({ where: { userId, title, createdAt: { gt: since } } })
65	    .catch(() => null);
66	  if (dupe) {
67	    console.error(`[game-update] ${serverId}: ${body} (customer already notified in the last 24h)`);
68	    return;
69	  }
70	  await notify(userId, title, body, href);
71	}
72	
73	/** Run the per-family update over SSH and verify the result. */
74	export async function gameUpdate(job: Job): Promise<void> {
75	  const server = await loadGameServer(job.serverId!);
76	  if (SANDBOX) {
77	    // No VM exists, so nothing can be proven. Say that, rather than simulating a
78	    // success message the production path is no longer willing to send.
79	    await notify(
80	      server.userId,
81	      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
82	      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
83	      `/dashboard/servers/${server.id}`
84	    );
85	    return;
86	  }
87	  const family = server.osTemplate.family as GameFamily;
88	  if (!GAME_FAMILIES.includes(family)) {
89	    throw new Error(`game update: ${server.hostname} is not a game server`);
90	  }
91	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
92	  const password = serverRootPassword(server);
93	  if (!connectionTarget(server) || !password) {
94	    throw new Error("game update: server has no IP/password yet");
95	  }
96	  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
97	  const href = `/dashboard/servers/${server.id}`;
98	
99	  const remote = updateCommand(family);
100	  let stdout = "";
101	  let connError: string | null = null;
102	  try {
103	    // Host/port come from connectionTarget() (dedicated IP, or this server's
104	    // OWN node's public IP + its NAT-forwarded sshPort) — never the guest's
105	    // private bridge IP, which the worker has no route to for a non-primary node.
106	    const r = await withServerSsh(server, (conn) => sshExecOn(conn, remote, 600_000));
107	    stdout = r.stdout;
108	  } catch (e: any) {
109	    connError = scrub(String(e?.message ?? e));
110	  }
111	
112	  // A non-zero exit (or a connection failure) is meaningful, but the markers may
113	  // still have been printed before whatever went wrong — check for them
114	  // regardless of how we got here and let the verdict decide, rather than
115	  // discarding evidence. Absence of the end marker is ALWAYS treated as an
116	  // unproven run, exit code notwithstanding — a clean SSH exit is not evidence.
117	  if (connError || !/^NXGU:END$/m.test(stdout)) {
118	    const detail = connError ?? (scrub(stdout).trim() || "no output — the update did not run to completion");
119	    const reason = `game update failed: ${detail}`;
120	    await notifyFailureOnce(
121	      server.userId,
122	      server.id,
123	      `${server.osTemplate.name} auto-update FAILED on ${server.hostname}`,
124	      `We could not reach or run the update on your server, so nothing was updated: ${detail.slice(0, 300)}`,
125	      href
126	    );
127	    throw new Error(reason);
128	  }
129	
130	  const facts = parseGameUpdateOutput(scrub(stdout));
131	  const verdict = judgeGameUpdate({ family, hostname: server.hostname, facts });
132	
133	  if (!verdict.ok) {
134	    await notifyFailureOnce(
135	      server.userId,
136	      server.id,
137	      `${server.osTemplate.name} auto-update did not complete on ${server.hostname}`,
138	      verdict.reason,
139	      href
140	    );
141	    // Failing the job is the point: it puts the reason in Job.error and in the
142	    // admin job list instead of leaving a green tick over a dead server.
143	    throw new Error(`game update not verified: ${verdict.reason}`);
144	  }
145	
146	  // Only a real change is an event. This runs every 6 hours, so notifying on
147	  // every pass produced four "<game> updated on <host>" messages a day for a
148	  // server where nothing had been updated — the same erosion `notifyFailureOnce`
149	  // exists to prevent, and with a title that was not true.
150	  if (verdict.notify) await notify(server.userId, verdict.title, verdict.body, href);
151	  else console.log(`[game-update] ${server.hostname}: ${verdict.title} — ${verdict.body}`);
152	}
153	
154	/**
155	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
156	 * auto-update and has no job already in flight. Idempotent / safe to call on a
157	 * timer. Returns nothing; logs a summary.
158	 */
159	export async function gameUpdateSweep(): Promise<void> {
160	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
161	  const allCandidates = await db.server.findMany({
162	    where: {
163	      status: "RUNNING",
164	      autoUpdate: true,
165	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
166	    },
167	    select: { id: true, hostname: true, gameConfig: true, osTemplate: { select: { family: true } } },
168	  });
169	  if (allCandidates.length === 0) return;
170	
171	  // Skip a server whose game SERVICE the customer deliberately stopped through
172	  // the dashboard — see eligibleForUpdateSweep's doc comment. `Server.status`
173	  // (checked above) is the VM's power state and can't see this.
174	  const candidates = allCandidates.filter((s) => eligibleForUpdateSweep(s.gameConfig));
175	  const skippedStopped = allCandidates.length - candidates.length;
176	
177	  let enqueued = 0;
178	  for (const s of candidates) {
179	    const inflight = await db.job.count({
180	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
181	    });
182	    if (inflight > 0) continue;
183	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
184	    enqueued++;
185	  }
186	  if (enqueued > 0 || skippedStopped > 0) {
187	    const checkOnly = candidates.filter((s) => !updatesFromSteam(s.osTemplate.family as GameFamily)).length;
188	    console.log(
189	      `[game-update] sweep enqueued ${enqueued} job(s)` +
190	        (checkOnly > 0
191	          ? ` (${checkOnly} candidate(s) are families with no update source — those runs verify the unit is ` +
192	            `up and change nothing)`
193	          : "") +
194	        (skippedStopped > 0
195	          ? ` (${skippedStopped} candidate(s) skipped — game service deliberately stopped by the customer)`
196	          : "")
197	    );
198	  }
199	}
