export type GameUpdateFacts = {
  /** The systemd unit the script acted on, or null when nothing matched. */
  unit: string | null;
  /** `systemctl is-active` before the restart. */
  wasActive: string;
  /** Exit code of `systemctl restart`, or null when it never ran. */
  restartRc: number | null;
  /** `systemctl is-active` after the restart, settled or timed out. */
  state: string;
  /**
   * "ok" = steamcmd downloaded a NEW build. "current" = it confirmed the server
   * was already up to date and downloaded nothing. Collapsing those two into one
   * value is what made "<game> updated on <host>" fire every 6 hours forever.
   */
  steam: "ok" | "current" | "failed" | "absent" | "na" | "unknown";
  steamRc: number | null;
  steamErrors: string[];
  /** Did the script run to completion? No END marker means we know nothing. */
  complete: boolean;

